<?php
namespace App\Http\Controllers;
use App\Services\Operations;use Illuminate\Http\Request;use Illuminate\Support\Facades\{DB,Cache,File};use Illuminate\Validation\ValidationException;
class ContentController extends Controller {
 public const GROUPS=['copy','services','portfolio','technologies','team'];
 public function index(){if(DB::table('site_contents')->count()===0){$seed=json_decode(File::get(database_path('seed-data/site.json')),true);foreach($seed as $key=>$value)DB::table('site_contents')->insertOrIgnore(['key'=>$key,'draft'=>json_encode($value,JSON_UNESCAPED_UNICODE),'version'=>1,'created_at'=>now(),'updated_at'=>now()]);}return ['items'=>DB::table('site_contents')->get()->map(fn($row)=>['key'=>$row->key,'draft'=>json_decode($row->draft,true),'published'=>$row->published?json_decode($row->published,true):null,'version'=>$row->version,'published_at'=>$row->published_at])];}
 private function validateContent(string $key,array $draft):void{
  $error=fn()=>throw ValidationException::withMessages(['draft'=>'The content structure is invalid. Check both language versions and required fields.']);if(strlen(json_encode($draft))>180000)$error();
  $walk=function($value,$depth=0)use(&$walk,$error){if($depth>8)$error();if(is_string($value)){if(mb_strlen($value)>10000)$error();return;}if(!is_array($value))$error();if(count($value)>100)$error();foreach($value as $child)$walk($child,$depth+1);};$walk($draft);
  if(in_array($key,['copy','services','portfolio'])){if(!isset($draft['en'],$draft['fa'])||array_diff(array_keys($draft),['en','fa']))$error();}
  if($key==='copy')foreach(['en','fa'] as $lang){$required=['heroLabel','heroTitle','heroText','footerStatement','servicesIntro','workIntro','techIntro','contactIntro'];if(array_diff(array_keys($draft[$lang]),$required)||array_diff($required,array_keys($draft[$lang])))$error();foreach($draft[$lang] as $value)if(!is_string($value)||trim($value)==='')$error();}
  if($key==='services')foreach(['en','fa'] as $lang){if(!array_is_list($draft[$lang])||count($draft[$lang])>12)$error();foreach($draft[$lang] as $item)foreach(['number','title','description','tags'] as $field)if(!isset($item[$field])||!is_string($item[$field]))$error();}
  if($key==='portfolio')foreach(['en','fa'] as $lang){if(!array_is_list($draft[$lang])||count($draft[$lang])>30)$error();foreach($draft[$lang] as $item){foreach(['category','title','description','challenge','approach'] as $field)if(!isset($item[$field])||!is_string($item[$field]))$error();foreach(['capabilities','tech','diagram'] as $field){if(!isset($item[$field])||!is_array($item[$field])||!array_is_list($item[$field])||count($item[$field])>20)$error();foreach($item[$field] as $text)if(!is_string($text))$error();}}}
  if($key==='technologies'){if(array_keys($draft)!==['items']||!is_array($draft['items'])||!array_is_list($draft['items']))$error();foreach($draft['items'] as $value)if(!is_string($value)||mb_strlen($value)>80)$error();}
  if($key==='team'){if(!isset($draft['people'])||count($draft['people'])!==2||array_column($draft['people'],'id')!==['saman','mohsen'])$error();foreach($draft['people'] as $person)foreach(['en','fa'] as $lang)if(!is_string($person['name'][$lang]??null)||!is_string($person['bio'][$lang]??null))$error();}
 }
 public function save(Request $r,string $key){abort_unless(in_array($key,self::GROUPS),404);$data=$r->validate(['draft'=>'required|array','version'=>'required|integer|min:1']);$this->validateContent($key,$data['draft']);DB::transaction(function()use($r,$key,$data){$row=DB::table('site_contents')->where('key',$key)->lockForUpdate()->first();abort_unless($row,404);abort_unless($row->version===$data['version'],409,'Content changed. Reload before saving.');DB::table('site_contents')->where('key',$key)->update(['draft'=>json_encode($data['draft'],JSON_UNESCAPED_UNICODE),'version'=>$row->version+1,'updated_by'=>$r->user()->id,'updated_at'=>now()]);Operations::log($r->user(),'content.saved','content',$key);});return ['ok'=>true];}
 public function publish(Request $r,string $key){$r->validate(['version'=>'required|integer']);DB::transaction(function()use($r,$key){$row=DB::table('site_contents')->where('key',$key)->lockForUpdate()->first();abort_unless($row&&in_array($key,self::GROUPS),404);abort_unless($row->version===$r->integer('version'),409,'Content changed. Reload before publishing.');$this->validateContent($key,json_decode($row->draft,true));DB::table('site_contents')->where('key',$key)->update(['published'=>$row->draft,'published_at'=>now(),'version'=>$row->version+1,'updated_at'=>now()]);Operations::log($r->user(),'content.published','content',$key);});Cache::forget('northbyte.public');$snapshot=$this->publicData();$target=config('northbyte.root').'/published-content.json';$temp=$target.'.tmp';File::put($temp,json_encode($snapshot,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));File::move($temp,$target);return ['ok'=>true];}
 public function publicData():array{return Cache::remember('northbyte.public',60,function(){$result=[];foreach(DB::table('site_contents')->whereNotNull('published')->get() as $row)$result[$row->key]=json_decode($row->published,true);$result['settings']=['brand'=>Operations::setting('brand','NorthByte'),'contactEmail'=>Operations::setting('contact_email','')];return $result;});}
}
